 "content": "def transform(grid):
    """Project each marker between aligned edge bars along paired vertical lanes."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Background is the most frequent color. Edge bars are contiguous runs of a
    # non-background color on the first and last rows, matched by their width.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(row):
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            end = c + 1
            while end < w and row[end] == row[c]:
                end += 1
            if end - c >= 2:
                runs.append((c, end))
            c = end
        return runs

    top_runs = edge_runs(grid[0])
    bottom_runs = edge_runs(grid[-1])
    matches = [(t, b) for t in top_runs for b in bottom_runs
               if t[1] - t[0] == b[1] - b[0]]
    if not matches:
        return out
    (top_start, top_end), (bottom_start, bottom_end) = matches[0]

    # Markers on either run project to their corresponding lane on the opposite
    # edge; the marker is the stopping point for the two opposing rays.
    markers = []
    for r in range(1, h - 1):
        for c in range(w):
            value = grid[r][c]
            if value == bg:
                continue
            if bottom_start <= c < bottom_end:
                markers.append((r, c, value, 'bottom', c - bottom_start))
            elif top_start <= c < top_end:
                markers.append((r, c, value, 'top', c - top_start))

    for r, c, value, side, offset in markers:
        opposite_c = (top_start if side == 'bottom' else bottom_start) + offset
        if side == 'bottom':
            for rr in range(1, r):
                out[rr][opposite_c] = value
            for rr in range(r + 1, h - 1):
                out[rr][c] = value
        else:
            for rr in range(1, r):
                out[rr][c] = value
            for rr in range(r + 1, h - 1):
                out[rr][opposite_c] = value

    for r, c, _, _, _ in markers:
        out[r][c] = 4
    return out

